const { seg, lerp, eo, eio, eob, clamp01 } = kit;
kit.scene('notes', {
  init(kit) {
    const r = kit.rng(12);
    // The sprig: a stem, tufts of needles along it, and its berries.
    let needles = '';
    for (let i = 0; i < 9; i++) {
      const s = 0.08 + i * 0.1, x = lerp(-120, 104, s) + 34 * Math.sin(s * 3), y = lerp(150, -150, s);
      for (let k = 0; k < 5; k++) {
        const a = (-150 + k * 30 + r() * 16) * Math.PI / 180, len = 44 + r() * 26 - i * 1.5;
        needles += 'M' + x.toFixed(0) + ' ' + y.toFixed(0) + ' l' + (len * Math.cos(a)).toFixed(0) + ' ' + (len * Math.sin(a)).toFixed(0) + ' ';
      }
    }
    const berry = (x, y, s) => '<circle cx="' + x + '" cy="' + y + '" r="' + s + '" style="fill:var(--deep)"/><circle cx="' + (x - s * 0.3) + '" cy="' + (y - s * 0.34) + '" r="' + (s * 0.3).toFixed(1) + '" style="fill:var(--fog);opacity:.5"/>';
    const item = (cls, word, art) => ({ cls, word, art });
    const items = [
      item('notes-honey', 'Honey', '<g transform="rotate(32)"><rect x="-10" y="-196" width="20" height="230" rx="10" style="fill:var(--brew)"/>' +
        [0, 1, 2, 3, 4].map((i) => '<ellipse cx="0" cy="' + (40 + i * 28) + '" rx="' + [40, 54, 58, 50, 34][i] + '" ry="17" style="fill:var(--second);stroke:var(--amber);stroke-width:5"/>').join('') +
        '<path d="M-36 58 C-42 96 -34 128 -16 150" style="fill:none;stroke:var(--glow);stroke-width:8;stroke-linecap:round"/><ellipse cx="0" cy="170" rx="15" ry="19" style="fill:var(--second)"/></g>' +
        '<path class="notes-thread" style="fill:none;stroke:var(--second);stroke-linecap:round"/><path class="notes-drop" d="M0 -26 C16 -4 16 14 0 14 C-16 14 -16 -4 0 -26 Z" style="fill:var(--second)"/>'),
      item('notes-apricot', 'Apricot', '<circle cx="-92" cy="64" r="84" style="fill:var(--amber)"/><path d="M-110 -16 C-132 30 -128 96 -100 146" style="fill:none;stroke:var(--accent);stroke-width:6;stroke-linecap:round;opacity:.7"/>' +
        '<circle cx="34" cy="24" r="112" style="fill:color-mix(in srgb, var(--second) 70%, var(--accent))"/>' +
        '<path d="M22 -86 C-12 -30 -10 62 26 134" style="fill:none;stroke:var(--accent);stroke-width:7;stroke-linecap:round;opacity:.75"/><path d="M-36 -22 C-30 -52 -14 -66 4 -70" style="fill:none;stroke:var(--ground);stroke-width:10;stroke-linecap:round;opacity:.55"/>' +
        '<g class="notes-leaf" transform="translate(24 -84)"><path d="M0 0 C-2 -18 2 -30 10 -40" style="fill:none;stroke:var(--brew);stroke-width:9;stroke-linecap:round"/><path d="M8 -34 C52 -92 124 -84 150 -58 C108 -16 44 -8 8 -34 Z" style="fill:var(--moss)"/><path d="M14 -36 C60 -62 104 -64 144 -58" style="fill:none;stroke:var(--main);stroke-width:4;opacity:.5"/></g>'),
      item('notes-juniper', 'Juniper', '<path d="' + needles + '" style="fill:none;stroke:var(--moss);stroke-width:9;stroke-linecap:round"/><path d="M-124 160 C-70 70 30 -20 108 -156" style="fill:none;stroke:var(--main);stroke-width:10;stroke-linecap:round"/>' +
        berry(-6, 58, 25) + berry(44, 22, 21) + berry(-52, 104, 20) + berry(62, -44, 18)),
    ];
    kit.stage.append(kit.h('<div class="ground notes-root"><div class="halo notes-halo" style="opacity:.55"></div>' +
      '<svg class="art" viewBox="0 0 1920 1080"><path class="notes-hill" d="' + W.ridge(kit, 23, 1010, 70).d + '" style="fill:var(--fog)"/>' +
      items.map((it, i) => '<g class="' + it.cls + '" transform="translate(' + (400 + i * 560) + ' 452)">' + it.art + '</g>').join('') + '</svg>' +
      '<div class="words" style="left:160px;top:96px;width:1600px;align-items:center"><p class="eyebrow notes-eyebrow">First Light tastes like</p></div>' +
      items.map((it, i) => '<div class="words notes-word" style="left:' + (120 + i * 560) + 'px;top:738px;width:560px;align-items:center;gap:8px"><h2 class="line" style="font-size:112px">' + it.word + '</h2>' +
        '<svg viewBox="0 0 300 26" width="300" height="26" style="overflow:visible"><path class="notes-rule" pathLength="1" d="M6 15 C70 4 130 22 190 11 S262 8 294 14" style="fill:none;stroke:var(--accent);stroke-width:8;stroke-linecap:round"/></svg></div>').join('') + '</div>'));
    const all = (s) => [...kit.stage.querySelectorAll(s)], q = (s) => kit.stage.querySelector(s);
    Object.assign(this, { arts: items.map((it) => q('.' + it.cls)), words: all('.notes-word'), rules: all('.notes-rule'), eyebrow: q('.notes-eyebrow'),
      halo: q('.notes-halo'), hill: q('.notes-hill'), thread: q('.notes-thread'), drop: q('.notes-drop'), leaf: q('.notes-leaf') });
  },
  render(t) {
    this.eyebrow.style.opacity = eo(seg(t, -0.3, 0.3)).toFixed(3);
    this.arts.forEach((art, i) => {
      // Each lands on its own beat with a little overshoot, then keeps a slow life of its own.
      const t0 = 0.15 + i * 0.75, a = seg(t, t0, t0 + 0.55), s = 1.18 * lerp(0.55, 1, eob(a, 1.7)) * (1 + 0.012 * Math.sin((t - t0) * 2.1));
      const turn = lerp([-14, 12, -16][i], 0, eo(a)) + 1.6 * Math.sin((t + i) * 1.3), y = 452 + lerp(46, 0, eo(a)) + 5 * Math.sin((t + i * 0.7) * 1.7);
      art.setAttribute('transform', 'translate(' + (400 + i * 560) + ' ' + y.toFixed(1) + ') rotate(' + turn.toFixed(2) + ') scale(' + s.toFixed(4) + ')');
      art.style.opacity = eo(seg(t, t0, t0 + 0.3)).toFixed(3);
      const w = eo(seg(t, t0 + 0.2, t0 + 0.7));
      this.words[i].style.opacity = w.toFixed(3);
      this.words[i].style.transform = 'translateY(' + ((1 - w) * 30).toFixed(1) + 'px)';
      this.rules[i].style.strokeDasharray = eio(seg(t, t0 + 0.5, t0 + 1.0)).toFixed(3) + ' 2';
      this.rules[i].style.opacity = t > t0 + 0.5 ? 1 : 0;
    });
    // Honey runs off the dipper: a thread that thins as its drop falls.
    const q = ((t - 0.9) * 0.55 % 1 + 1) % 1, fall = 6 + 44 * q * q, on = seg(t, 0.9, 1.2);
    this.thread.setAttribute('d', 'M-99 150 V' + (156 + fall).toFixed(1));
    this.thread.style.strokeWidth = (9 * (1 - q) + 1).toFixed(1);
    this.thread.style.opacity = (on * (1 - seg(q, 0.75, 1))).toFixed(3);
    this.drop.setAttribute('transform', 'translate(-99 ' + (162 + fall).toFixed(1) + ') scale(' + (0.8 + 0.5 * seg(q, 0, 0.5)).toFixed(3) + ')');
    this.drop.style.opacity = (on * (1 - seg(q, 0.8, 1))).toFixed(3);
    this.leaf.setAttribute('transform', 'translate(24 -84) rotate(' + (4 * Math.sin(t * 1.9)).toFixed(2) + ')');
    this.halo.style.transform = 'translate(360px,' + lerp(420, 330, eio(seg(t, 0, 4.5))).toFixed(1) + 'px)';
    this.hill.style.transform = 'translateX(' + (-30 * t / 4.5).toFixed(1) + 'px)';
  },
});
